import numpy as np
import pandas as pd


def generate(observed, spec, seed):
    model = spec['model']
    t = np.asarray(spec['tc_mg_dl'], dtype=float)
    h = np.asarray(spec['hdl_mg_dl'], dtype=float)
    n = int(spec['task']['n_rows'])
    if t.shape != (n,) or h.shape != (n,) or n < 2:
        raise ValueError('Marginal sizes do not match n_rows.')
    if not (np.all(np.isfinite(t)) and np.all(np.isfinite(h))):
        raise ValueError('Nonfinite marginal value.')
    if np.any(t <= 0) or np.any(h <= 0):
        raise ValueError('Concentrations must be positive.')
    if np.any(np.diff(t) < 0) or np.any(np.diff(h) < 0):
        raise ValueError('Marginals must be sorted ascending.')
    if np.any(h > t):
        raise ValueError('No HDL <= TC permutation exists for these marginals.')

    rng = np.random.default_rng(seed)
    target = float(model['evidence']['mean_individual_ratio']['value'])
    tol = float(model['ratio_numerical_tolerance'])
    x = np.log(t)
    sx = float(x.std())
    if sx == 0:
        raise ValueError('Degenerate TC marginal cannot support this calibration.')
    x = (x - x.mean()) / sx
    noise = rng.standard_normal(n)
    ranks = np.arange(n, dtype=np.int64)

    def candidate(rho):
        score = rho * x + np.sqrt(max(0.0, 1.0 - rho * rho)) * noise
        order = np.argsort(score, kind='mergesort')
        p = np.empty(n, dtype=np.int64)
        p[order] = ranks
        # Process TC from smallest to largest. A violating row receives the
        # smallest remaining HDL. All earlier rows remain unchanged.
        for i in range(n):
            if h[p[i]] > t[i]:
                j = i + int(np.argmin(h[p[i:]]))
                if h[p[j]] > t[i]:
                    raise RuntimeError('Feasibility repair failed.')
                p[i], p[j] = p[j], p[i]
        return p, float(np.mean(t / h[p]))

    lo, hi = map(float, model['latent_correlation_bounds'])
    p_lo, r_lo = candidate(lo)
    p_hi, r_hi = candidate(hi)
    if abs(r_lo - target) <= abs(r_hi - target):
        best, best_ratio = p_lo.copy(), r_lo
    else:
        best, best_ratio = p_hi.copy(), r_hi

    for _ in range(int(model['calibration_iterations'])):
        mid = (lo + hi) / 2.0
        p, r = candidate(mid)
        if abs(r - target) < abs(best_ratio - target):
            best, best_ratio = p.copy(), r
        if abs(best_ratio - target) <= tol:
            break
        # More concordant ranks ordinarily lower E(TC/HDL).
        # Keep the best feasible candidate even if repair causes a small
        # local departure from monotonicity.
        if r > target:
            lo = mid
        else:
            hi = mid

    # Correct only any residual ratio discrepancy; do not optimize the
    # non-HDL threshold frequency. Each accepted swap preserves feasibility
    # and strictly improves the ratio fit.
    p = best
    current = float(np.mean(t / h[p]))
    limit = int(model['maximum_residual_swap_proposals'])
    for _ in range(limit):
        if abs(current - target) <= tol:
            break
        i = int(rng.integers(n))
        j = int(rng.integers(n))
        if i == j:
            continue
        a, b = int(p[i]), int(p[j])
        if h[b] > t[i] or h[a] > t[j]:
            continue
        delta = (t[i] - t[j]) * (1.0 / h[b] - 1.0 / h[a]) / n
        proposed = current + delta
        if abs(proposed - target) < abs(current - target):
            p[i], p[j] = b, a
            current = proposed

    actual_ratio = float(np.mean(t / h[p]))
    if abs(actual_ratio - target) > tol:
        raise RuntimeError('Could not attain the required ratio calibration.')
    if np.any(h[p] > t):
        raise RuntimeError('HDL exceeds TC.')
    if not np.array_equal(np.sort(p), ranks):
        raise RuntimeError('HDL indices are not a permutation.')
    if abs(actual_ratio - target) > 0.02 or round(actual_ratio, 2) != round(target, 2):
        raise RuntimeError('Published ratio precision check failed.')

    return pd.DataFrame({'row_id': ranks, 'hdl_index': p})

