import numpy as np
import pandas as pd


def generate(observed, spec, seed):
    if observed is not None:
        raise ValueError('This model does not use participant observations.')
    model = spec['model']
    t = np.asarray(spec['tc_mg_dl'], dtype=float)
    h = np.asarray(spec['hdl_mg_dl'], dtype=float)
    n = int(spec['task']['n_rows'])
    if t.shape != (n,) or h.shape != (n,) or n < 2:
        raise ValueError('Unexpected marginal dimensions.')
    if not (np.all(np.isfinite(t)) and np.all(np.isfinite(h))):
        raise ValueError('Nonfinite concentrations.')
    if np.any(t <= 0) or np.any(h <= 0):
        raise ValueError('Concentrations must be positive.')
    if np.any(np.diff(t) < 0) or np.any(np.diff(h) < 0):
        raise ValueError('Marginals must be ascending.')
    if np.any(h > t):
        raise ValueError('No permutation can satisfy HDL <= TC for these marginals.')

    target = float(model['evidence']['mean_individual_ratio']['value'])
    tol = float(model['ratio_calibration_tolerance'])
    rng = np.random.default_rng(seed)
    z = np.log(t)
    sd = z.std()
    if sd == 0:
        raise ValueError('TC marginal has zero variation.')
    z = (z - z.mean()) / sd
    noise = rng.standard_normal(n)
    indices = np.arange(n, dtype=np.int64)

    def assignment(rho):
        score = rho * z + np.sqrt(max(0.0, 1.0 - rho * rho)) * noise
        order = np.argsort(score, kind='stable')
        p = np.empty(n, dtype=np.int64)
        p[order] = indices
        # Ascending repair leaves every previously processed row feasible.
        # Prefer a swap making both affected rows feasible immediately.
        for i in range(n):
            if h[p[i]] <= t[i]:
                continue
            eligible = np.flatnonzero(h[p[i + 1:]] <= t[i]) + i + 1
            if eligible.size == 0:
                raise RuntimeError('Feasibility repair failed.')
            both = eligible[t[eligible] >= h[p[i]]]
            k = int(both[0] if both.size else eligible[-1])
            p[i], p[k] = p[k], p[i]
        ratio = float(np.mean(t / h[p]))
        return p, ratio

    lo, hi = map(float, model['initial_latent_correlation_bounds'])
    plo, rlo = assignment(lo)
    phi, rhi = assignment(hi)
    if not (rhi <= target <= rlo):
        lo, hi = map(float, model['fallback_latent_correlation_bounds'])
        plo, rlo = assignment(lo)
        phi, rhi = assignment(hi)
    if not (rhi <= target <= rlo):
        raise ValueError('Reported ratio is outside this assignment family.')
    if abs(rlo - target) < abs(rhi - target):
        best_p, best_r = plo, rlo
    else:
        best_p, best_r = phi, rhi
    for _ in range(int(model['maximum_calibration_iterations'])):
        if abs(best_r - target) <= tol:
            break
        mid = (lo + hi) / 2.0
        p, r = assignment(mid)
        if abs(r - target) < abs(best_r - target):
            best_p, best_r = p, r
        if r > target:
            lo = mid
        else:
            hi = mid

    if abs(best_r - target) > tol or round(best_r, 2) != round(target, 2):
        raise RuntimeError('Ratio calibration did not reach the required precision.')
    if not np.array_equal(np.sort(best_p), indices):
        raise RuntimeError('HDL indices are not a permutation.')
    if np.any(h[best_p] > t):
        raise RuntimeError('HDL exceeds TC.')

    # These are diagnostics only; neither estimand is an optimization target.
    nonhdl = t - h[best_p]
    if not np.isclose(nonhdl.mean(), t.mean() - h.mean(), rtol=0, atol=1e-9):
        raise RuntimeError('Non-HDL mean identity failed.')
    prevalence = 100.0 * np.mean(nonhdl >= float(model['nonhdl_threshold_mg_dl']))
    if not (0.0 <= prevalence <= 100.0):
        raise RuntimeError('Invalid prevalence.')
    return pd.DataFrame({'row_id': indices, 'hdl_index': best_p})
